import { useState } from "react";
import { Check, ChevronLeft, ChevronRight } from "lucide-react";

const Page = () => {
  const [step, setStep] = useState(1);

  const [formData, setFormData] = useState({
    name: "",
    email: "",
    age: "",
    username: "",
    password: "",
  });

  const [error, setError] = useState("");

  const steps = [
    {
      number: 1,
      title: "Personal",
    },
    {
      number: 2,
      title: "Account",
    },
    {
      number: 3,
      title: "Review",
    },
  ];

  const handleChange = (e) => {
    const { name, value } = e.target;

    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));

    setError("");
  };

  const handleNext = () => {
    setError("");

    if (step === 1) {
      if (!formData.name.trim() || !formData.email.trim() || !formData.age) {
        setError("Please fill in all personal information.");
        return;
      }

      if (!formData.email.includes("@")) {
        setError("Please enter a valid email address.");
        return;
      }

      if (Number(formData.age) < 1) {
        setError("Please enter a valid age.");
        return;
      }
    }

    if (step === 2) {
      if (!formData.username.trim() || !formData.password) {
        setError("Please fill in all account information.");
        return;
      }

      if (formData.username.length < 3) {
        setError("Username must be at least 3 characters.");
        return;
      }

      if (formData.password.length < 6) {
        setError("Password must be at least 6 characters.");
        return;
      }
    }

    setStep((prev) => prev + 1);
  };

  const handlePrevious = () => {
    setError("");
    setStep((prev) => prev - 1);
  };

  const handleSubmit = () => {
    console.log("Final Form Data:", formData);

    alert("Form submitted successfully!");

    setStep(1);
    setFormData({
      name: "",
      email: "",
      age: "",
      username: "",
      password: "",
    });
  };

  return (
    <main className="min-h-screen bg-slate-50 px-5 py-10 sm:px-10">
      <div className="mx-auto w-full max-w-2xl">
        {/* Card */}
        <section className="rounded-3xl border border-slate-200 bg-white p-6 shadow-xl shadow-slate-200/60 sm:p-8">
          {/* Header */}
          <div className="mb-8 text-center">
            <p className="text-sm font-semibold uppercase tracking-[0.2em] text-blue-600">
              Registration
            </p>

            <h1 className="mt-2 text-2xl font-bold text-slate-800 sm:text-3xl">
              Create Your Account
            </h1>

            <p className="mt-2 text-sm text-slate-500">
              Complete the steps below to create your account.
            </p>
          </div>

          {/* Progress */}
          <div className="mb-10">
            <div className="flex items-center justify-between">
              {steps.map((item, index) => {
                const isCompleted = step > item.number;
                const isActive = step === item.number;

                return (
                  <div key={item.number} className="flex flex-1 items-center">
                    <div className="flex flex-col items-center">
                      <div
                        className={`flex size-10 items-center justify-center rounded-full text-sm font-semibold transition-all duration-300 ${
                          isCompleted
                            ? "bg-blue-600 text-white"
                            : isActive
                              ? "bg-blue-600 text-white ring-4 ring-blue-100"
                              : "bg-slate-100 text-slate-400"
                        }`}
                      >
                        {isCompleted ? (
                          <Check className="size-5" />
                        ) : (
                          item.number
                        )}
                      </div>

                      <span
                        className={`mt-2 text-xs font-medium sm:text-sm ${
                          isActive || isCompleted
                            ? "text-blue-600"
                            : "text-slate-400"
                        }`}
                      >
                        {item.title}
                      </span>
                    </div>

                    {index < steps.length - 1 && (
                      <div
                        className={`mx-2 mb-6 h-0.5 flex-1 transition-all duration-300 ${
                          step > item.number ? "bg-blue-600" : "bg-slate-200"
                        }`}
                      />
                    )}
                  </div>
                );
              })}
            </div>
          </div>

          {/* Step 1 */}
          {step === 1 && (
            <div className="space-y-5">
              <div>
                <h2 className="text-xl font-bold text-slate-800">
                  Personal Information
                </h2>

                <p className="mt-1 text-sm text-slate-500">
                  Tell us a little about yourself.
                </p>
              </div>

              <div>
                <label className="mb-2 block text-sm font-medium text-slate-700">
                  Full Name
                </label>

                <input
                  type="text"
                  name="name"
                  placeholder="Enter your name"
                  value={formData.name}
                  onChange={handleChange}
                  className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-700 outline-none transition focus:border-blue-400 focus:ring-4 focus:ring-blue-100"
                />
              </div>

              <div>
                <label className="mb-2 block text-sm font-medium text-slate-700">
                  Email Address
                </label>

                <input
                  type="email"
                  name="email"
                  placeholder="Enter your email"
                  value={formData.email}
                  onChange={handleChange}
                  className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-700 outline-none transition focus:border-blue-400 focus:ring-4 focus:ring-blue-100"
                />
              </div>

              <div>
                <label className="mb-2 block text-sm font-medium text-slate-700">
                  Age
                </label>

                <input
                  type="number"
                  name="age"
                  min="1"
                  placeholder="Enter your age"
                  value={formData.age}
                  onChange={handleChange}
                  className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-700 outline-none transition focus:border-blue-400 focus:ring-4 focus:ring-blue-100"
                />
              </div>
            </div>
          )}

          {/* Step 2 */}
          {step === 2 && (
            <div className="space-y-5">
              <div>
                <h2 className="text-xl font-bold text-slate-800">
                  Account Information
                </h2>

                <p className="mt-1 text-sm text-slate-500">
                  Create your login credentials.
                </p>
              </div>

              <div>
                <label className="mb-2 block text-sm font-medium text-slate-700">
                  Username
                </label>

                <input
                  type="text"
                  name="username"
                  placeholder="Enter username"
                  value={formData.username}
                  onChange={handleChange}
                  className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-700 outline-none transition focus:border-blue-400 focus:ring-4 focus:ring-blue-100"
                />
              </div>

              <div>
                <label className="mb-2 block text-sm font-medium text-slate-700">
                  Password
                </label>

                <input
                  type="password"
                  name="password"
                  placeholder="Enter password"
                  value={formData.password}
                  onChange={handleChange}
                  className="w-full rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-700 outline-none transition focus:border-blue-400 focus:ring-4 focus:ring-blue-100"
                />
              </div>
            </div>
          )}

          {/* Step 3 */}
          {step === 3 && (
            <div>
              <div className="mb-6">
                <h2 className="text-xl font-bold text-slate-800">
                  Review Information
                </h2>

                <p className="mt-1 text-sm text-slate-500">
                  Check your information before submitting.
                </p>
              </div>

              <div className="divide-y divide-slate-100 rounded-2xl border border-slate-200">
                <div className="flex justify-between gap-4 p-4">
                  <span className="text-sm text-slate-500">Name</span>
                  <span className="text-right text-sm font-semibold text-slate-800">
                    {formData.name}
                  </span>
                </div>

                <div className="flex justify-between gap-4 p-4">
                  <span className="text-sm text-slate-500">Email</span>
                  <span className="text-right text-sm font-semibold text-slate-800">
                    {formData.email}
                  </span>
                </div>

                <div className="flex justify-between gap-4 p-4">
                  <span className="text-sm text-slate-500">Age</span>
                  <span className="text-right text-sm font-semibold text-slate-800">
                    {formData.age}
                  </span>
                </div>

                <div className="flex justify-between gap-4 p-4">
                  <span className="text-sm text-slate-500">Username</span>
                  <span className="text-right text-sm font-semibold text-slate-800">
                    {formData.username}
                  </span>
                </div>

                <div className="flex justify-between gap-4 p-4">
                  <span className="text-sm text-slate-500">Password</span>
                  <span className="text-right text-sm font-semibold text-slate-800">
                    ••••••••
                  </span>
                </div>
              </div>
            </div>
          )}

          {/* Error */}
          {error && (
            <div className="mt-5 rounded-xl border border-red-100 bg-red-50 px-4 py-3">
              <p className="text-sm font-medium text-red-600">{error}</p>
            </div>
          )}

          {/* Buttons */}
          <div className="mt-8 flex items-center justify-between gap-4">
            {step > 1 ? (
              <button
                type="button"
                onClick={handlePrevious}
                className="flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-5 py-2.5 text-sm font-semibold text-slate-600 transition hover:bg-slate-50 hover:text-slate-900 active:scale-95"
              >
                <ChevronLeft className="size-4" />
                Previous
              </button>
            ) : (
              <div />
            )}

            {step < 3 ? (
              <button
                type="button"
                onClick={handleNext}
                className="flex items-center gap-2 rounded-xl bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white shadow-lg shadow-blue-500/20 transition hover:bg-blue-700 active:scale-95"
              >
                Next
                <ChevronRight className="size-4" />
              </button>
            ) : (
              <button
                type="button"
                onClick={handleSubmit}
                className="flex items-center gap-2 rounded-xl bg-green-600 px-5 py-2.5 text-sm font-semibold text-white shadow-lg shadow-green-500/20 transition hover:bg-green-700 active:scale-95"
              >
                <Check className="size-4" />
                Submit
              </button>
            )}
          </div>
        </section>
      </div>
    </main>
  );
};

export default Page;

"use client";

import { useState } from "react";
import { Minus, Plus, ShoppingCart, Trash2, PackageOpen } from "lucide-react";

const initialProducts = [
  {
    id: 1,
    name: "Keyboard",
    price: 1500,
    quantity: 1,
  },
  {
    id: 2,
    name: "Mouse",
    price: 800,
    quantity: 1,
  },
  {
    id: 3,
    name: "Headphone",
    price: 2500,
    quantity: 1,
  },
];

const Page = () => {
  const [cart, setCart] = useState(initialProducts);

  const increaseQuantity = (id) => {
    setCart((prevCart) =>
      prevCart.map((item) =>
        item.id === id
          ? {
              ...item,
              quantity: item.quantity + 1,
            }
          : item,
      ),
    );
  };

  const decreaseQuantity = (id) => {
    setCart((prevCart) =>
      prevCart
        .map((item) =>
          item.id === id
            ? {
                ...item,
                quantity: item.quantity - 1,
              }
            : item,
        )
        .filter((item) => item.quantity > 0),
    );
  };

  const removeItem = (id) => {
    setCart((prevCart) => prevCart.filter((item) => item.id !== id));
  };

  const totalPrice = cart.reduce(
    (total, item) => total + item.price * item.quantity,
    0,
  );

  const totalItems = cart.reduce((total, item) => total + item.quantity, 0);

  const formatPrice = (price) => {
    return `₹${price.toLocaleString("en-IN")}`;
  };

  return (
    <main className="min-h-screen bg-slate-50 px-5 py-10 sm:px-8">
      <div className="mx-auto w-full max-w-4xl">
        {/* Header */}
        <div className="mb-8 flex items-center gap-4">
          <div className="flex size-12 items-center justify-center rounded-2xl bg-blue-50 text-blue-600">
            <ShoppingCart className="size-6" />
          </div>

          <div>
            <h1 className="text-2xl font-bold text-slate-800 sm:text-3xl">
              Shopping Cart
            </h1>

            <p className="mt-1 text-sm text-slate-500">
              {totalItems} {totalItems === 1 ? "item" : "items"} in your cart
            </p>
          </div>
        </div>

        {cart.length === 0 ? (
          /* Empty Cart */
          <section className="rounded-3xl border border-slate-200 bg-white px-6 py-16 text-center shadow-lg shadow-slate-200/50">
            <div className="mx-auto flex size-16 items-center justify-center rounded-full bg-slate-100 text-slate-400">
              <PackageOpen className="size-8" />
            </div>

            <h2 className="mt-5 text-xl font-bold text-slate-800">
              Your cart is empty
            </h2>

            <p className="mt-2 text-sm text-slate-500">
              You don't have any products in your cart yet.
            </p>
          </section>
        ) : (
          <div className="grid gap-6 lg:grid-cols-[1fr_320px]">
            {/* Cart Items */}
            <section className="space-y-4">
              {cart.map((item) => (
                <div
                  key={item.id}
                  className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm transition hover:shadow-md"
                >
                  <div className="flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between">
                    {/* Product Info */}
                    <div className="flex items-center gap-4">
                      <div className="flex size-12 shrink-0 items-center justify-center rounded-xl bg-slate-100 text-slate-500">
                        <ShoppingCart className="size-5" />
                      </div>

                      <div>
                        <h2 className="font-semibold text-slate-800">
                          {item.name}
                        </h2>

                        <p className="mt-1 text-sm text-slate-500">
                          {formatPrice(item.price)} per item
                        </p>
                      </div>
                    </div>

                    {/* Quantity + Total */}
                    <div className="flex items-center justify-between gap-5 sm:justify-end">
                      {/* Quantity Controls */}
                      <div className="flex items-center rounded-xl border border-slate-200 bg-slate-50">
                        <button
                          type="button"
                          onClick={() => decreaseQuantity(item.id)}
                          aria-label={`Decrease ${item.name} quantity`}
                          className="flex size-9 items-center justify-center text-slate-500 transition hover:bg-white hover:text-slate-900"
                        >
                          <Minus className="size-4" />
                        </button>

                        <span className="flex w-9 items-center justify-center text-sm font-semibold text-slate-800">
                          {item.quantity}
                        </span>

                        <button
                          type="button"
                          onClick={() => increaseQuantity(item.id)}
                          aria-label={`Increase ${item.name} quantity`}
                          className="flex size-9 items-center justify-center text-slate-500 transition hover:bg-white hover:text-slate-900"
                        >
                          <Plus className="size-4" />
                        </button>
                      </div>

                      {/* Item Total */}
                      <div className="min-w-24 text-right">
                        <p className="text-xs text-slate-400">Subtotal</p>

                        <p className="mt-1 font-bold text-slate-800">
                          {formatPrice(item.price * item.quantity)}
                        </p>
                      </div>

                      {/* Remove */}
                      <button
                        type="button"
                        onClick={() => removeItem(item.id)}
                        aria-label={`Remove ${item.name}`}
                        className="flex size-9 items-center justify-center rounded-xl text-slate-400 transition hover:bg-red-50 hover:text-red-500"
                      >
                        <Trash2 className="size-4" />
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </section>

            {/* Order Summary */}
            <aside className="h-fit rounded-2xl border border-slate-200 bg-white p-6 shadow-sm lg:sticky lg:top-6">
              <h2 className="text-lg font-bold text-slate-800">
                Order Summary
              </h2>

              <div className="mt-5 space-y-4 text-sm">
                <div className="flex justify-between text-slate-500">
                  <span>Items</span>
                  <span>{totalItems}</span>
                </div>

                <div className="flex justify-between text-slate-500">
                  <span>Subtotal</span>
                  <span>{formatPrice(totalPrice)}</span>
                </div>

                <div className="flex justify-between text-slate-500">
                  <span>Shipping</span>
                  <span className="font-medium text-green-600">Free</span>
                </div>
              </div>

              <div className="my-5 border-t border-slate-100" />

              <div className="flex items-center justify-between">
                <span className="font-semibold text-slate-700">Total</span>

                <span className="text-xl font-bold text-slate-900">
                  {formatPrice(totalPrice)}
                </span>
              </div>

              <button
                type="button"
                className="mt-6 flex w-full items-center justify-center gap-2 rounded-xl bg-blue-600 px-5 py-3 text-sm font-semibold text-white shadow-lg shadow-blue-500/20 transition hover:bg-blue-700 active:scale-[0.98]"
              >
                Proceed to Checkout
              </button>
            </aside>
          </div>
        )}
      </div>
    </main>
  );
};

export default Page;
